/**
 * The decoder behind /tools/heart-rate-lab.
 *
 * One plain-ESM module with no dependencies and no network call, imported by
 * the page's client component and by scripts/hr-measurement.test.mjs, so the
 * test runs exactly the code a reader runs.
 *
 * It does not know the Heart Rate Measurement (0x2A37) layout. The layout is
 * compiled from the Bluetooth SIG's GATT Specification Supplement structure in
 * src/data/bluetoothGatt.ts (generated by scripts/fetch-bluetooth-gatt.mjs),
 * which the page reads on the server and hands to `compileHrmLayout`:
 *
 *   - field order, gss types and sizes          ← `gss.structure`
 *   - which flags bit makes each field present  ← each field's parsed
 *                                                 "Present if bit N of Flags
 *                                                 field is set to V" line
 *   - units                                     ← each field's `units`
 *   - what every flags bit means                ← the Flags `bits` definition
 *   - the RR-interval resolution and how many   ← the RR-Interval definition's
 *     RR values a packet carries                  own sentences, kept as evidence
 *
 * Anything the structure does not describe in a form this module understands
 * (a type other than uintN / uintN[n], a field not conditional on Flags, a
 * repeated field that is not last) throws, so a change in the SIG's file fails
 * the test instead of silently mis-decoding.
 *
 * Two things are not in the SIG's YAML and are stated here with their source:
 *   - byte order: little-endian, as the Web Bluetooth specification's own
 *     heart-rate example reads every uint16 (BYTE_ORDER_SOURCE);
 *   - Battery Level (0x2A19), outside the generator's scope, read from the
 *     SIG's own gss file at the same commit (BATTERY_LEVEL).
 */

/** Where little-endian comes from. The SIG's YAML files do not state byte order. */
export const BYTE_ORDER_SOURCE = {
  url: "https://webbluetoothcg.github.io/web-bluetooth/#example-heart-rate-monitor",
  readFrom: "https://raw.githubusercontent.com/WebBluetoothCG/web-bluetooth/main/index.bs",
  fetchedOn: "2026-10-31",
  quote: "result.heartRate = data.getUint16(index, /*littleEndian=*/true);",
  /** The same example's comment on Energy Expended, which reads the value as kJ. */
  energyComment: "energyExpended: 750,     // Meaning 750kJ.",
};

/**
 * Battery Level, read from the Bluetooth SIG's public repository on
 * 2026-10-31 at the commit src/data/bluetoothGatt.ts was generated from
 * (408f4a0305d87ea75d9f700e3c8f85aa1d3a74fd). The UUIDs are from
 * assigned_numbers/uuids/service_uuids.yaml and characteristic_uuids.yaml;
 * the lines are the gss file's field description, verbatim.
 */
export const BATTERY_LEVEL = {
  serviceUuid: 0x180f,
  serviceName: "Battery",
  serviceId: "org.bluetooth.service.battery_service",
  uuid: 0x2a19,
  name: "Battery Level",
  id: "org.bluetooth.characteristic.battery_level",
  type: "uint8",
  size: 1,
  unitId: "org.bluetooth.unit.percentage",
  lines: [
    "Base Unit: org.bluetooth.unit.percentage.",
    "Allowed range is 0 to 100.",
    "100% represents fully charged; 0% represents fully discharged.",
    "All other values are reserved for future use.",
  ],
  min: 0,
  max: 100,
  file: "gss/org.bluetooth.characteristic.battery_level.yaml",
  fetchedOn: "2026-10-31",
};

/* ---------------------------------------------------------------------- *
 * Compiling the SIG structure
 * ---------------------------------------------------------------------- */

const UINT = /^uint(8|16|24|32)(\[n\])?$/;

/** "0" → [0]; "5–7" (en dash or hyphen) → [5, 6, 7]. */
function bitList(s) {
  const m = /^(\d+)\s*[–-]\s*(\d+)$/.exec(String(s).trim());
  if (m) {
    const out = [];
    for (let i = Number(m[1]); i <= Number(m[2]); i++) out.push(i);
    return out;
  }
  if (/^\d+$/.test(String(s).trim())) return [Number(s)];
  throw new Error(`Unrecognised bit "${s}" in the Flags definition`);
}

/** The sentence of `text` that matches `re`, or null. */
function sentence(text, re) {
  if (!text) return null;
  return text.split(/(?<=\.)\s+/).find((x) => re.test(x)) ?? null;
}

/**
 * Compile a characteristic record from src/data/bluetoothGatt.ts (0x2A37) into
 * the layout `decodeHrm` and `encodeHrm` use. Pure; the result is plain JSON so
 * a server component can pass it to a client one.
 */
export function compileHrmLayout(c) {
  const structure = c?.gss?.structure;
  const defs = c?.gss?.definitions ?? [];
  if (!structure?.length) throw new Error(`${c?.uuid ?? "characteristic"} has no gss structure`);

  const flags = structure[0];
  if (flags.type !== "boolean[8]" || flags.sizeN !== 1 || flags.offset !== 0) {
    throw new Error(`Expected a one-octet boolean[8] Flags field first, got ${flags.type} (${flags.size})`);
  }
  const flagsDef = defs.find((d) => d.kind === "bits" && d.name === flags.name);
  if (!flagsDef) throw new Error(`No bits definition for ${flags.name}`);
  const bits = flagsDef.rows.map((r) => ({
    bits: bitList(r.bit),
    label: r.bit,
    description: r.description,
    reserved: /Reserved for Future Use/i.test(r.description),
  }));
  const bitWith = (re) => {
    const row = bits.find((b) => b.bits.length === 1 && re.test(b.description.trim()));
    return row ? row.bits[0] : null;
  };

  const fields = structure.slice(1).map((f, i, rest) => {
    const m = UINT.exec(f.type);
    if (!m) throw new Error(`${f.name}: unsupported gss type "${f.type}"`);
    if (!f.presence || f.presence.field !== flags.name) {
      throw new Error(`${f.name}: expected a "Present if bit N of ${flags.name} field" condition`);
    }
    const repeated = !!m[2];
    if (repeated && i !== rest.length - 1) throw new Error(`${f.name}: a repeated field must be last`);
    const width = Number(m[1]) / 8;
    const unit = f.units[0] ? { id: f.units[0].id, name: f.units[0].name, evidence: f.units[0].evidence } : null;

    let scale = null;
    let countRule = null;
    if (repeated) {
      const def = defs.find((d) => d.name.toLowerCase() === f.name.toLowerCase());
      const resolution = sentence(def?.description, /\b1\/(\d+) second\b/);
      const divisor = resolution ? Number(/\b1\/(\d+) second\b/.exec(resolution)[1]) : null;
      scale = divisor ? { divisor, label: `1/${divisor} s`, evidence: resolution } : null;
      countRule = sentence(def?.description, /number of .* present is determined by/i);
    }
    const kind = repeated
      ? "rr"
      : unit?.id === "org.bluetooth.unit.period.beats_per_minute"
        ? "hr"
        : unit?.id === "org.bluetooth.unit.energy.joule"
          ? "energy"
          : "other";
    return {
      name: f.name,
      anchor: f.anchor,
      type: f.type,
      size: f.size,
      width,
      repeated,
      kind,
      presence: { bit: f.presence.bit, value: f.presence.value, evidence: f.presence.evidence },
      unit,
      scale,
      countRule,
    };
  });

  return {
    uuid: c.uuid,
    uuidNumber: parseInt(c.uuid, 16),
    id: c.id,
    name: c.name,
    file: c.gss.file,
    flagsName: flags.name,
    flagsAnchor: flags.anchor,
    bits,
    contactDetectedBit: bitWith(/^Sensor Contact detected$/i),
    contactSupportedBit: bitWith(/^Sensor Contact Supported$/i),
    fields,
    byteOrder: "little-endian",
  };
}

/**
 * Compile Body Sensor Location (0x2A38) value rows: "0x01" → Chest,
 * "0x07–0xFF" → Reserved for Future Use.
 */
export function compileBodySensorLocation(c) {
  const f = c?.gss?.structure?.[0];
  const def = c?.gss?.definitions?.find((d) => d.kind === "values");
  if (!f || f.type !== "uint8" || !def) throw new Error("Body Sensor Location: expected one uint8 field with a values table");
  return {
    uuid: c.uuid,
    uuidNumber: parseInt(c.uuid, 16),
    name: c.name,
    rows: def.rows.map((r) => {
      const [a, b] = String(r.value).split(/\s*[–-]\s*/);
      return { from: parseInt(a, 16), to: parseInt(b ?? a, 16), value: r.value, description: r.description };
    }),
  };
}

export function decodeBodySensorLocation(input, bsl) {
  const bytes = toBytes(input);
  if (bytes.length < 1) return { value: null, description: null, error: "empty value" };
  const v = bytes[0];
  const row = bsl.rows.find((r) => v >= r.from && v <= r.to);
  return { value: v, description: row ? row.description : null, error: row ? null : "value not in the SIG's table" };
}

export function decodeBatteryLevel(input) {
  const bytes = toBytes(input);
  if (bytes.length < 1) return { value: null, inRange: false, error: "empty value" };
  const v = bytes[0];
  const inRange = v >= BATTERY_LEVEL.min && v <= BATTERY_LEVEL.max;
  return { value: v, inRange, error: inRange ? null : "reserved for future use" };
}

/* ---------------------------------------------------------------------- *
 * Bytes
 * ---------------------------------------------------------------------- */

/** Uint8Array from a Uint8Array, DataView, ArrayBuffer or number[]. */
export function toBytes(input) {
  if (input instanceof Uint8Array) return input;
  if (typeof DataView !== "undefined" && input instanceof DataView) {
    return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  }
  if (input instanceof ArrayBuffer) return new Uint8Array(input);
  if (Array.isArray(input)) return Uint8Array.from(input);
  throw new Error("Expected bytes");
}

export function toHex(input, sep = " ") {
  return Array.from(toBytes(input), (b) => b.toString(16).toUpperCase().padStart(2, "0")).join(sep);
}

/** "1E 46 EE 02", "1e46ee02", "0x1E,0x46" → bytes; null when it is not hex. */
export function parseHex(text) {
  const parts = String(text)
    .trim()
    .split(/[\s,:;]+/)
    .filter(Boolean)
    .map((p) => p.replace(/^0x/i, ""));
  if (parts.length === 0) return null;
  const joined = parts.every((p) => p.length <= 2) ? parts.map((p) => p.padStart(2, "0")).join("") : parts.join("");
  if (!/^[0-9a-f]*$/i.test(joined) || joined.length % 2 !== 0) return null;
  const out = new Uint8Array(joined.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(joined.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function readUintLE(bytes, off, width) {
  let v = 0;
  for (let i = width - 1; i >= 0; i--) v = v * 256 + bytes[off + i];
  return v;
}

function writeUintLE(out, v, width) {
  for (let i = 0; i < width; i++) {
    out.push(v % 256);
    v = Math.floor(v / 256);
  }
}

/* ---------------------------------------------------------------------- *
 * Decode and encode 0x2A37
 * ---------------------------------------------------------------------- */

const isPresent = (flags, p) => ((flags >> p.bit) & 1) === p.value;

/**
 * Decode one Heart Rate Measurement value against a compiled layout.
 *
 * Returns every flags bit with the SIG's description, every field (present or
 * not, with the condition that decided it), byte spans for highlighting, and
 * the convenience values heartRate / energyExpended / rr (raw) / rrMs.
 * Problems are reported in `errors`, never thrown: this runs on whatever a
 * device sends.
 */
export function decodeHrm(input, layout) {
  const bytes = toBytes(input);
  const out = {
    length: bytes.length,
    hex: toHex(bytes),
    flags: null,
    bits: [],
    reservedSet: [],
    fields: [],
    spans: [],
    heartRate: null,
    hrFormat: null,
    energyExpended: null,
    rr: [],
    rrMs: [],
    rrPresent: false,
    sensorContact: "unknown",
    trailing: 0,
    errors: [],
  };
  if (bytes.length === 0) {
    out.errors.push("Empty value: not even the Flags octet.");
    return out;
  }
  const flags = bytes[0];
  out.flags = flags;
  out.spans.push({ start: 0, end: 1, kind: "flags", label: layout.flagsName });
  out.bits = layout.bits.map((b) => ({
    label: b.label,
    description: b.description,
    reserved: b.reserved,
    values: b.bits.map((i) => (flags >> i) & 1),
  }));
  out.reservedSet = layout.bits.filter((b) => b.reserved).flatMap((b) => b.bits.filter((i) => (flags >> i) & 1));

  const { contactDetectedBit: det, contactSupportedBit: sup } = layout;
  if (det != null && sup != null) {
    out.sensorContact = (flags >> sup) & 1 ? ((flags >> det) & 1 ? "detected" : "not detected") : "not supported";
  }

  let off = 1;
  let stopped = false;
  for (const f of layout.fields) {
    const present = isPresent(flags, f.presence);
    const base = { name: f.name, anchor: f.anchor, type: f.type, kind: f.kind, unit: f.unit, presence: f.presence, present };
    if (!present || stopped) {
      out.fields.push({ ...base, present: present && !stopped, offset: null, length: 0, value: null, values: null });
      continue;
    }
    if (!f.repeated) {
      if (off + f.width > bytes.length) {
        out.errors.push(
          `${f.name} is flagged present and needs ${f.width} octet${f.width > 1 ? "s" : ""} at offset ${off}; the value has ${bytes.length - off}.`,
        );
        out.fields.push({ ...base, offset: off, length: 0, value: null, values: null });
        stopped = true;
        continue;
      }
      const v = readUintLE(bytes, off, f.width);
      out.fields.push({ ...base, offset: off, length: f.width, value: v, values: null });
      out.spans.push({ start: off, end: off + f.width, kind: f.kind, label: f.name });
      if (f.kind === "hr") {
        out.heartRate = v;
        out.hrFormat = f.type;
      } else if (f.kind === "energy") out.energyExpended = v;
      off += f.width;
    } else {
      const n = Math.floor((bytes.length - off) / f.width);
      const values = [];
      for (let i = 0; i < n; i++) {
        const s = off + i * f.width;
        values.push(readUintLE(bytes, s, f.width));
        out.spans.push({ start: s, end: s + f.width, kind: f.kind, label: `${f.name} ${i}` });
      }
      out.fields.push({ ...base, offset: off, length: n * f.width, value: null, values });
      out.rrPresent = true;
      out.rr = values;
      out.rrMs = f.scale ? values.map((v) => (v * 1000) / f.scale.divisor) : [];
      if (n === 0) out.errors.push(`${f.name} is flagged present but the value carries no ${f.name} octets.`);
      off += n * f.width;
    }
  }
  if (!stopped && off < bytes.length) {
    out.trailing = bytes.length - off;
    out.spans.push({ start: off, end: bytes.length, kind: "trailing", label: "Not described by the structure" });
    out.errors.push(`${out.trailing} octet${out.trailing > 1 ? "s" : ""} left over after the last field the flags announce.`);
  }
  return out;
}

/**
 * Build a 0x2A37 value from the compiled layout. Used for the synthetic
 * replay and the tests. Presence bits are set from each field's own
 * condition, so the flags byte is whatever the SIG's structure says it must be.
 *
 *   heartRate      required
 *   hr16           true → the uint16 heart-rate field (else uint8)
 *   contact        "not supported" | "not detected" | "detected"
 *   energyExpended number → included
 *   rr             number[] (raw, in the field's resolution) → included
 *   reservedBits   extra bits to set, for testing
 */
export function encodeHrm(layout, { heartRate, hr16 = false, contact = "not supported", energyExpended = null, rr = null, reservedBits = [] }) {
  const want = (f) => (f.kind === "hr" ? (f.width === 2) === hr16 : f.kind === "energy" ? energyExpended != null : f.kind === "rr" ? rr != null : false);
  const assigned = new Map();
  const assign = (bit, v) => {
    if (assigned.has(bit) && assigned.get(bit) !== v) throw new Error(`Flags bit ${bit} is asked to be both 0 and 1`);
    assigned.set(bit, v);
  };
  for (const f of layout.fields) assign(f.presence.bit, want(f) ? f.presence.value : 1 - f.presence.value);
  if (layout.contactSupportedBit != null) assign(layout.contactSupportedBit, contact === "not supported" ? 0 : 1);
  if (layout.contactDetectedBit != null) assign(layout.contactDetectedBit, contact === "detected" ? 1 : 0);
  for (const b of reservedBits) assign(b, 1);
  let flags = 0;
  for (const [bit, v] of assigned) if (v) flags |= 1 << bit;

  const out = [flags];
  for (const f of layout.fields) {
    if (!want(f)) continue;
    if (f.kind === "hr") writeUintLE(out, heartRate, f.width);
    else if (f.kind === "energy") writeUintLE(out, energyExpended, f.width);
    else if (f.kind === "rr") for (const v of rr) writeUintLE(out, v, f.width);
  }
  return Uint8Array.from(out);
}

/* ---------------------------------------------------------------------- *
 * RMSSD
 * ---------------------------------------------------------------------- */

/**
 * RMSSD over runs of consecutive RR intervals, in ms: the square root of the
 * mean squared difference between successive intervals. Differences are
 * taken only inside a run, never across a disconnect or a gap, so pass one
 * array per uninterrupted run. Null when there is no pair to difference.
 * No artefact filtering: this is a demonstration, not a measurement.
 */
export function rmssd(runs) {
  let sum = 0;
  let n = 0;
  for (const run of runs) {
    for (let i = 1; i < run.length; i++) {
      const d = run[i] - run[i - 1];
      sum += d * d;
      n++;
    }
  }
  return n === 0 ? null : { value: Math.sqrt(sum / n), differences: n };
}

/* ---------------------------------------------------------------------- *
 * Synthetic session (labelled synthetic wherever it is shown)
 * ---------------------------------------------------------------------- */

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * A SYNTHETIC session: one notification per second, generated here, not
 * recorded from any device. Heart rate and RR values are made up and
 * physiologically illustrative only. The phases exist to exercise the
 * decoder: uint8 and uint16 heart-rate formats, all three contact states,
 * Energy Expended, and a stretch with no RR intervals at all.
 */
export const SYNTHETIC_PHASES = [
  { from: 0, to: 20, note: "uint8 heart rate, contact detected, RR intervals", hr16: false, contact: "detected", energy: false, rr: true },
  { from: 20, to: 28, note: "contact not detected, no RR intervals", hr16: false, contact: "not detected", energy: false, rr: false },
  { from: 28, to: 45, note: "uint16 heart-rate format, RR intervals", hr16: true, contact: "detected", energy: false, rr: true },
  { from: 45, to: 55, note: "Energy Expended included, RR intervals", hr16: false, contact: "detected", energy: true, rr: true },
  { from: 55, to: 70, note: "contact not supported, no RR intervals (a device that never sends them)", hr16: false, contact: "not supported", energy: false, rr: false },
  { from: 70, to: 90, note: "uint8 heart rate, contact detected, RR intervals", hr16: false, contact: "detected", energy: false, rr: true },
];

export function syntheticSession(layout, { seconds = 90, seed = 2026 } = {}) {
  const rand = mulberry32(seed);
  const rrField = layout.fields.find((f) => f.kind === "rr");
  const divisor = rrField?.scale?.divisor ?? 1024;
  const out = [];
  let beatClock = 0; // ms, time of the last beat
  let beat = 0;
  let energy = 40;
  for (let s = 0; s < seconds; s++) {
    const phase = SYNTHETIC_PHASES.find((p) => s >= p.from && s < p.to) ?? SYNTHETIC_PHASES[0];
    const bpm = 64 + 7 * Math.sin((2 * Math.PI * s) / 45) + (rand() - 0.5) * 2;
    const rrRaw = [];
    const end = (s + 1) * 1000;
    // Beats that complete inside this second; a breathing-like swing plus noise.
    while (true) {
      const ms = (60000 / bpm) * (1 + 0.05 * Math.sin((2 * Math.PI * beat) / 4.5)) + (rand() - 0.5) * 18;
      if (beatClock + ms > end) break;
      beatClock += ms;
      beat++;
      rrRaw.push(Math.round((ms * divisor) / 1000));
    }
    energy += 1;
    const bytes = encodeHrm(layout, {
      heartRate: Math.round(bpm),
      hr16: phase.hr16,
      contact: phase.contact,
      energyExpended: phase.energy ? energy : null,
      // A second in which no beat completed carries no RR values, so the bit stays clear.
      rr: phase.rr && rrRaw.length > 0 ? rrRaw : null,
    });
    out.push({ tMs: s * 1000, bytes, note: phase.note });
  }
  return out;
}

/* ---------------------------------------------------------------------- *
 * CSV
 * ---------------------------------------------------------------------- */

const csvCell = (v) => {
  const s = v == null ? "" : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

/**
 * rows: { tMs, at (ISO string), source ("device" | "synthetic"), bytes }.
 * Every row is re-decoded here, so the CSV says what the decoder says.
 */
export function sessionCsv(rows, layout) {
  const header = [
    "t_ms",
    "received_at",
    "source",
    "hex",
    "flags",
    "hr_format",
    "heart_rate_bpm",
    "sensor_contact",
    "energy_expended_raw",
    "rr_raw",
    "rr_ms",
    "errors",
  ];
  const lines = [header.join(",")];
  for (const r of rows) {
    const d = decodeHrm(r.bytes, layout);
    lines.push(
      [
        r.tMs,
        r.at,
        r.source,
        d.hex,
        d.flags == null ? "" : `0x${d.flags.toString(16).toUpperCase().padStart(2, "0")}`,
        d.hrFormat ?? "",
        d.heartRate ?? "",
        d.sensorContact,
        d.energyExpended ?? "",
        d.rr.join(" "),
        d.rrMs.map((v) => v.toFixed(1)).join(" "),
        d.errors.join(" | "),
      ]
        .map(csvCell)
        .join(","),
    );
  }
  return lines.join("\n") + "\n";
}
